Rules.InvariantScript:
If(
    IsBlank(txtPatientMessage.Text),
    Notify("Please type a message first.", NotificationType.Error),

    Set(
        vPatientRequest,
        Patch(
            PatientRequests,
            LookUp(PatientRequests, ID = vPatientRequest.ID),
            {
                PatientMessage:
                    Coalesce(
                        LookUp(PatientRequests, ID = vPatientRequest.ID).PatientMessage,
                        ""
                    ) &
                    If(
                        IsBlank(LookUp(PatientRequests, ID = vPatientRequest.ID).PatientMessage),
                        "",
                        Char(10) & Char(10)
                    ) &
                    Text(Now(), "hh:mm AM/PM") &
                    " - Patient: " &
                    txtPatientMessage.Text
            }
        )
    );

    Notify("Message sent", NotificationType.Success);
    Reset(txtPatientMessage)
)

Set(
    vPatientRequest,
    Patch(
        PatientRequests,
        LookUp(PatientRequests, ID = vPatientRequest.ID),
        {
            RequestStatus: {Value: "Completed"}
        }
    )
);

Notify("Request completed", NotificationType.Success);




Navigate(DoneHelp, ScreenTransition.Fade)
